import urllib.request, json, urllib.parse, time

def batch_urls(files):
    files = [f for f in files if f][:10]
    if not files: return {}
    titles = '|'.join('File:' + f for f in files)
    enc = urllib.parse.quote(titles)
    url_api = f'https://commons.wikimedia.org/w/api.php?action=query&titles={enc}&prop=imageinfo&iiprop=url&iiurlwidth=800&format=json'
    req = urllib.request.Request(url_api, headers={'User-Agent': 'AuraVaultBot/1.0'})
    try:
        with urllib.request.urlopen(req, timeout=15) as r:
            data = json.loads(r.read())
        result = {}
        for p in data['query']['pages'].values():
            title = p.get('title','').replace('File:','')
            ii = p.get('imageinfo',[])
            if ii and ii[0].get('thumburl'):
                result[title] = ii[0]['thumburl']
        return result
    except Exception as e:
        return {'_err': str(e)}

def search_commons(query, limit=5):
    enc = urllib.parse.quote(query)
    url = f'https://commons.wikimedia.org/w/api.php?action=query&list=search&srsearch={enc}&srnamespace=6&srlimit={limit}&format=json'
    req = urllib.request.Request(url, headers={'User-Agent': 'AuraVaultBot/1.0'})
    try:
        with urllib.request.urlopen(req, timeout=12) as r:
            data = json.loads(r.read())
        return [r['title'].replace('File:','') for r in data['query']['search']]
    except:
        return []

image_exts = ('.jpg','.jpeg','.png','.JPG','.JPEG','.PNG','.gif')

# Search with different terms - focus on interior gallery views
searches = [
    'Rijksmuseum Gallery Honour interior',
    'museum room interior Europe paintings walls',
    'Alte Pinakothek room interior',
    'Prado museum sala interior paintings walls',
    'Uffizi interior gallery room',
    'Kunsthistorisches Museum interior gallery',
]
found = []
for q in searches:
    res = search_commons(q, 5)
    imgs = [r for r in res if any(r.lower().endswith(e.lower()) for e in image_exts)]
    if imgs:
        print(f'== {q[:50]} ==')
        for i in imgs[:2]:
            print(f'  {i[:95]}')
        found.extend(imgs[:2])
    time.sleep(0.6)

if found:
    print('\n--- Fetching ---')
    time.sleep(1)
    urls = batch_urls(found[:10])
    for fname, url in urls.items():
        if '_err' not in fname:
            print(f'OK {fname[:70]}: {url[:95]}')
